{
  "name": "opencode-memory-monorepo",
  "version": "0.1.2",
  "description": "opencode 本地持久记忆插件：三层记忆（长期知识/情景摘要/会话工作记忆），纯本地 SQLite + jieba 中文检索",
  "type": "module",
  "private": true,
  "workspaces": [
    "packages/*"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/aifcoding/opencode-memory.git"
  },
  "keywords": [
    "opencode",
    "plugin",
    "memory",
    "sqlite",
    "jieba",
    "rag",
    "ai"
  ],
  "scripts": {
    "test": "bun test packages/core/tests packages/opencode/tests packages/mcp/tests",
    "typecheck": "bun run --cwd packages/core typecheck && bun run --cwd packages/opencode typecheck && bun run --cwd packages/mcp typecheck",
    "build": "bun run --cwd packages/core build && bun run --cwd packages/opencode build && bun run --cwd packages/mcp build",
    "format": "biome format --write packages/core/src packages/core/tests packages/opencode/src packages/opencode/tests packages/mcp/src packages/mcp/tests examples package.json tsconfig.base.json biome.json",
    "format:check": "biome format packages/core/src packages/core/tests packages/opencode/src packages/opencode/tests packages/mcp/src packages/mcp/tests examples package.json tsconfig.base.json biome.json",
    "prepublishOnly": "bun run typecheck && bun test && bun run build"
  },
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@biomejs/biome": "2.5.13"
  }
}

{
  "name": "@aifcoding/memory-core",
  "version": "0.3.0",
  "description": "Framework-independent memory storage primitives",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./sqlite": {
      "types": "./dist/sqlite/index.d.ts",
      "import": "./dist/sqlite/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/aifcoding/opencode-memory.git"
  },
  "keywords": [
    "ai",
    "memory",
    "core",
    "sqlite",
    "retrieval"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "bun test tests",
    "typecheck": "tsc --noEmit",
    "build": "rm -rf dist && bun build src/index.ts src/sqlite/index.ts --outdir dist --target bun --external jieba-wasm && tsc -p tsconfig.build.json --declaration --emitDeclarationOnly --noEmit false --outDir dist",
    "prepublishOnly": "bun run typecheck && bun test && bun run build"
  },
  "dependencies": {
    "jieba-wasm": "^2.4.0"
  },
  "devDependencies": {
    "@types/bun": "^1.4.2",
    "typescript": "^7.0.2"
  }
}

{
  "name": "@aifcoding/memory-mcp",
  "version": "0.2.0",
  "type": "module",
  "main": "./dist/index.js",
  "bin": {
    "memory-mcp": "./dist/cli.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@aifcoding/memory-core": "^0.3.0",
    "@modelcontextprotocol/server": "2.0.0",
    "jsonc-parser": "^3.3.1",
    "zod": "^4.2.0"
  },
  "devDependencies": {
    "@types/bun": "^1.4.2",
    "typescript": "^7.0.2"
  },
  "scripts": {
    "test": "bun test tests",
    "typecheck": "tsc --noEmit",
    "build": "rm -rf dist && bun build src/index.ts src/cli.ts --outdir dist --target bun --external @aifcoding/memory-core --external '@aifcoding/memory-core/*' --external jieba-wasm --external @modelcontextprotocol/server --external zod --external jsonc-parser && tsc -p tsconfig.build.json --declaration --emitDeclarationOnly --noEmit false --outDir dist"
  }
}

{
  "name": "@aifcoding/opencode-memory",
  "version": "2.2.2",
  "description": "opencode 本地持久记忆插件",
  "type": "module",
  "main": "dist/plugin.js",
  "module": "dist/plugin.js",
  "exports": {
    ".": "./dist/plugin.js",
    "./server": "./dist/plugin.js"
  },
  "files": [
    "dist"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/aifcoding/opencode-memory.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@aifcoding/memory-core": "^0.3.0",
    "jsonc-parser": "^3.3.1",
    "zod": "4.1.8"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.30",
    "@types/bun": "^1.4.2",
    "typescript": "^7.0.2"
  },
  "scripts": {
    "test": "bun test tests",
    "typecheck": "tsc --noEmit",
    "build": "bun build src/plugin.ts --outdir dist --target bun --external @aifcoding/memory-core --external jieba-wasm --external zod --external jsonc-parser",
    "prepublishOnly": "bun run typecheck && bun test && bun run build"
  }
}
